import { test, expect } from '@playwright/test';

test.describe('Character Count on Textarea', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/form');
  });

  test('should display character count and limit input to 500 characters', async ({ page }) => {
    // Verify textarea is visible and has initial count
    const textarea = page.getByLabel('Message');
    await expect(textarea).toBeVisible();
    const countDisplay = page.getByText('0/500');
    await expect(countDisplay).toBeVisible();

    // Type less than 500 characters
    await textarea.fill('This is a test message.');
    await expect(countDisplay).toContainText('25/500');

    // Type exactly 500 characters
    const fullMessage = 'A'.repeat(500);
    await textarea.fill(fullMessage);
    await expect(countDisplay).toContainText('500/500');

    // Verify character count is not exceeded
    const inputLength = await textarea.inputValue();
    expect(inputLength.length).toBe(500);

    // Attempt to type one more character
    await textarea.fill(fullMessage + 'A');
    await expect(countDisplay).toContainText('500/500');
    const exceededLength = await textarea.inputValue();
    expect(exceededLength.length).toBe(500);

    // Verify submit button is enabled
    const submitButton = page.getByRole('button', { name: /submit/i });
    await expect(submitButton).toBeEnabled();
  });

  test('should handle empty textarea and display correct count', async ({ page }) => {
    // Verify textarea is visible and count is 0
    const textarea = page.getByLabel('Message');
    const countDisplay = page.getByText('0/500');
    await expect(textarea).toBeVisible();
    await expect(countDisplay).toBeVisible();

    // Clear textarea
    await textarea.clear();
    await expect(countDisplay).toContainText('0/500');

    // Verify submit button is disabled when textarea is empty
    const submitButton = page.getByRole('button', { name: /submit/i });
    await expect(submitButton).toBeDisabled();

    // Type a short message
    await textarea.fill('Hello world');
    await expect(countDisplay).toContainText('11/500');

    // Verify submit button is enabled
    await expect(submitButton).toBeEnabled();

    // Verify character count updates as user deletes text
    await textarea.clear();
    await expect(countDisplay).toContainText('0/500');
    await expect(submitButton).toBeDisabled();
  });
});
